INSERT INTO `system_home_component` VALUES (20, 2, '欢迎组件', 'workbench_welcome', 'dashboard/home/components/welcome/workbench-welcome.vue', '展示欢迎信息、用户信息和天气，支持和风天气API', NULL, 24, 4, '{\r\n    \"properties\": [\r\n      {\r\n        \"key\": \"greeting\",\r\n        \"type\": \"string\",\r\n        \"label\": \"提示语\",\r\n        \"default\": \"欢迎回来，开始您的工作吧！\",\r\n        \"required\": false\r\n      },\r\n      {\r\n        \"key\": \"showWeather\",\r\n        \"type\": \"boolean\",\r\n        \"label\": \"显示天气\",\r\n        \"default\": true,\r\n        \"required\": false\r\n      },\r\n      {\r\n        \"key\": \"weatherApiKey\",\r\n        \"type\": \"string\",\r\n        \"label\": \"和风天气API Key\",\r\n        \"default\": \"\",\r\n        \"required\": false\r\n      },\r\n      {\r\n        \"key\": \"paddingTop\",\r\n        \"type\": \"number\",\r\n        \"label\": \"内边距-上(px)\",\r\n        \"default\": 0,\r\n        \"min\": 0,\r\n        \"max\": 100,\r\n        \"required\": false\r\n      },\r\n      {\r\n        \"key\": \"paddingRight\",\r\n        \"type\": \"number\",\r\n        \"label\": \"内边距-右(px)\",\r\n        \"default\": 0,\r\n        \"min\": 0,\r\n        \"max\": 100,\r\n        \"required\": false\r\n      },\r\n      {\r\n        \"key\": \"paddingBottom\",\r\n        \"type\": \"number\",\r\n        \"label\": \"内边距-下(px)\",\r\n        \"default\": 0,\r\n        \"min\": 0,\r\n        \"max\": 100,\r\n        \"required\": false\r\n      },\r\n      {\r\n        \"key\": \"paddingLeft\",\r\n        \"type\": \"number\",\r\n        \"label\": \"内边距-左(px)\",\r\n        \"default\": 0,\r\n        \"min\": 0,\r\n        \"max\": 100,\r\n        \"required\": false\r\n      },\r\n      {\r\n        \"key\": \"marginTop\",\r\n        \"type\": \"number\",\r\n        \"label\": \"外边距-上(px)\",\r\n        \"default\": 0,\r\n        \"min\": 0,\r\n        \"max\": 100,\r\n        \"required\": false\r\n      },\r\n      {\r\n        \"key\": \"marginRight\",\r\n        \"type\": \"number\",\r\n        \"label\": \"外边距-右(px)\",\r\n        \"default\": 0,\r\n        \"min\": 0,\r\n        \"max\": 100,\r\n        \"required\": false\r\n      },\r\n      {\r\n        \"key\": \"marginBottom\",\r\n        \"type\": \"number\",\r\n        \"label\": \"外边距-下(px)\",\r\n        \"default\": 0,\r\n        \"min\": 0,\r\n        \"max\": 100,\r\n        \"required\": false\r\n      },\r\n      {\r\n        \"key\": \"marginLeft\",\r\n        \"type\": \"number\",\r\n        \"label\": \"外边距-左(px)\",\r\n        \"default\": 0,\r\n        \"min\": 0,\r\n        \"max\": 100,\r\n        \"required\": false\r\n      }\r\n    ]\r\n  }', 0, 5, '1', '2026-01-09 16:00:00', '', '2026-01-09 16:00:00', b'0', 1);
